contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        address ownerBefore;
        bool reverted;
        try c.owner() returns (address o) { ownerBefore = o; reverted = false; } catch { reverted = true; }
